SELECT QUARTER(opened_date) AS opened_quarter, ROUND(AVG(balance), 2) AS avg_balance, ROUND((100 * SUM(CASE WHEN account_type = 'CREDIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_credit, MIN(balance) AS min_balance FROM accounts WHERE customer_id IN (12, 16, 23, 27) AND balance < 58000 AND account_type IN ('SAVINGS', 'CREDIT') GROUP BY opened_quarter;
